PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settlements(id TEXT PRIMARY KEY,agreement_id TEXT NOT NULL,gross_sat INTEGER NOT NULL,network TEXT NOT NULL,status TEXT NOT NULL,max_total_fee_sat INTEGER NOT NULL,snapshot_json TEXT NOT NULL,created_at TEXT NOT NULL,approved_at TEXT,completed_at TEXT);
CREATE TABLE IF NOT EXISTS settlement_items(id TEXT PRIMARY KEY,settlement_id TEXT NOT NULL REFERENCES settlements(id),role TEXT NOT NULL,recipient_did TEXT NOT NULL,recipient_name TEXT NOT NULL,weight INTEGER NOT NULL,amount_sat INTEGER NOT NULL,invoice TEXT,invoice_hash TEXT UNIQUE,payment_hash TEXT UNIQUE,status TEXT NOT NULL,fee_limit_sat INTEGER NOT NULL,actual_fee_sat INTEGER,failure_code TEXT,failure_message TEXT,started_at TEXT,completed_at TEXT,UNIQUE(settlement_id,id,invoice_hash));
CREATE TABLE IF NOT EXISTS payment_attempts(id TEXT PRIMARY KEY,settlement_item_id TEXT NOT NULL REFERENCES settlement_items(id),idempotency_key TEXT NOT NULL UNIQUE,payment_hash TEXT NOT NULL UNIQUE,status TEXT NOT NULL,lnd_payment_index TEXT,failure_reason TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,settlement_id TEXT NOT NULL,settlement_item_id TEXT,type TEXT NOT NULL,metadata_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS receipts(id INTEGER PRIMARY KEY AUTOINCREMENT,settlement_id TEXT NOT NULL,entry_json TEXT NOT NULL);
